{"kind":"stack","id":"teeth-stack","title":"Types of teeth and what they do","theme":{"background":"#fdf6e3","foreground":"#073642","font":"Georgia, serif"}}
{"kind":"card","card":{"id":"c1","kind":"flash","elements":[{"type":"text","id":"c1-t","content":"Incisor"},{"type":"text","id":"c1-e","content":"A sharp front tooth used for cutting food."},{"type":"button","id":"c1-b","label":"Next Card","actions":[{"type":"goto","cardId":"c2"}]}],"actions":[]}}
{"kind":"card","card":{"id":"c2","kind":"flash","elements":[{"type":"text","id":"c2-t","content":"Molar"},{"type":"text","id":"c2-e","content":"A broad back tooth used for grinding and chewing food."},{"type":"button","id":"c2-b","label":"Next Card","actions":[{"type":"goto","cardId":"c3"}]}],"actions":[]}}
{"kind":"card","card":{"id":"c3","kind":"quiz","elements":[{"type":"text","id":"c3-q","content":"Which teeth are used for cutting food?"},{"type":"button","id":"c3-a","label":"Incisors","actions":[{"type":"score","delta":1},{"type":"sound","sound":"cheer"},{"type":"goto","cardId":"c4"}]},{"type":"button","id":"c3-b","label":"Molars","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c4"}]},{"type":"button","id":"c3-c","label":"Canines","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c4"}]}],"actions":[]}}
{"kind":"card","card":{"id":"c4","kind":"quiz","elements":[{"type":"text","id":"c4-q","content":"How many teeth does a typical adult human have?"},{"type":"button","id":"c4-a","label":"32","actions":[{"type":"score","delta":1},{"type":"sound","sound":"cheer"},{"type":"goto","cardId":"c5"}]},{"type":"button","id":"c4-b","label":"20","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c5"}]},{"type":"button","id":"c4-c","label":"24","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c5"}]}],"actions":[]}}
{"kind":"card","card":{"id":"c5","kind":"story","elements":[{"type":"image","picto":"bulb"},{"type":"text","id":"c5-t","content":"You bite into a crunchy apple. Which tooth do you use first?"},{"type":"button","id":"c5-a","label":"A sharp front tooth","actions":[{"type":"goto","cardId":"c6"}]},{"type":"button","id":"c5-b","label":"A broad back tooth","actions":[{"type":"goto","cardId":"c7"}]}],"actions":[]}}
{"kind":"card","card":{"id":"c6","kind":"story","elements":[{"type":"text","id":"c6-t","content":"Yes! Your incisors bite into the apple and cut off a piece. Well done."},{"type":"button","id":"c6-b","label":"Continue","actions":[{"type":"goto","cardId":"c8"}]}],"actions":[]}}
{"kind":"card","card":{"id":"c7","kind":"story","elements":[{"type":"text","id":"c7-t","content":"Your molars are good at grinding, but they are at the back. Your incisors go first to cut the apple."},{"type":"button","id":"c7-b","label":"Continue","actions":[{"type":"goto","cardId":"c8"}]}],"actions":[]}}
{"kind":"card","card":{"id":"c8","kind":"quiz","elements":[{"type":"text","id":"c8-q","content":"Which teeth are best for grinding food?"},{"type":"button","id":"c8-a","label":"Molars","actions":[{"type":"score","delta":1},{"type":"sound","sound":"cheer"},{"type":"goto","cardId":"c9"}]},{"type":"button","id":"c8-b","label":"Incisors","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c9"}]},{"type":"button","id":"c8-c","label":"Canines","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c9"}]}],"actions":[]}}
{"kind":"card","card":{"id":"c9","kind":"quiz","elements":[{"type":"text","id":"c9-q","content":"Which tooth is pointed and used for tearing food?"},{"type":"button","id":"c9-a","label":"Canine","actions":[{"type":"score","delta":1},{"type":"sound","sound":"cheer"},{"type":"goto","cardId":"c10"}]},{"type":"button","id":"c9-b","label":"Premolar","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c10"}]},{"type":"button","id":"c9-c","label":"Molar","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c10"}]}],"actions":[]}}
{"kind":"card","card":{"id":"c10","kind":"quiz","elements":[{"type":"text","id":"c10-q","content":"Which teeth sit between the canines and the molars?"},{"type":"button","id":"c10-a","label":"Premolars","actions":[{"type":"score","delta":1},{"type":"sound","sound":"cheer"},{"type":"goto","cardId":"c11"}]},{"type":"button","id":"c10-b","label":"Incisors","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c11"}]},{"type":"button","id":"c10-c","label":"Wisdom teeth","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c11"}]}],"actions":[]}}
{"kind":"card","card":{"id":"c11","kind":"end","elements":[{"type":"text","id":"c11-h","content":"You finished the teeth quiz!"},{"type":"text","id":"c11-m","content":"Great work. You now know the four types of teeth and what each one is for."}],"actions":[]}}
